variants.extern:
extern unsigned char far status[3];
extern long far ticks[3];

void far step(int index, long delta)
{
    status[index] = 0x2f;
    ticks[index] += delta;
}

long far pick(int left, int right)
{
    if (ticks[left] > ticks[right])
        return ticks[right];
    return ticks[left];
}

